from pathlib import Path
import json,re
from datetime import datetime,timezone,timedelta
p=Path('work/shinhan');m=json.loads((p/'manifest.json').read_text(encoding='utf8'));r=[]
now=datetime.now(timezone(timedelta(hours=9))).isoformat(sep=' ',timespec='seconds')
def doc(k):return next(x for x in m if x['key']==k)
def add(k,product,coverage,target,amount,conditions,pages,bpages,review=''):
 f=doc(k);b=next(x for x in m if x['product']==f['product'] and x['kind']=='사업방법서')
 r.append(dict(id=len(r)+1,company_name='신한라이프',product_name=product,coverage_name=coverage,coverage_target=target,coverage_amount=amount,coverage_conditions=conditions,created_at=now,updated_at=now,source_file=f['path'],source_page=pages,business_file=b['path'],business_page=bpages,review=review or '약관 지급기준표·관련 조항과 사업방법서를 대조. 실제 지급액은 계약의 선택종목·납입·인출 내용을 적용.'))
disability='연금개시 전에 발생한 동일 재해에 따른 장해이며, 그 기간 중 장해상태가 되어야 합니다. 최초 1회 지급합니다. 동일 재해의 서로 다른 신체부위 장해는 합산하되 동일 부위·파생장해는 약관상 중복 제한을 적용합니다. 장해가 180일 이내 확정되지 않으면 180일 시점의 의사 진단을 적용하고, 장해분류표의 별도 판정시기는 그 기준을 따릅니다. 5년 이상 한시장해는 해당 장해지급률의 20%로 판정합니다. 고의 자해·계약자 또는 수익자의 고의 가해는 면책하되 심신상실 등 약관상 예외를 적용합니다.'
dollar_elig='일시납 계약으로 최소거치기간은 10년입니다. 가입나이는 0세~(연금개시나이−10)세, 연금개시나이는 30~85세입니다. 기본보험료는 US$10,000~US$7,000,000이며 회사의 별도 인수 기준이 적용될 수 있습니다.'
dollar_interest='금액은 미화(US$)로 산정·지급합니다. 가입시 공시이율은 계약일부터 10년의 이율확정기간에 확정 적용하고 이후에는 변경된 공시이율을 적용합니다. 최저보증 공시이율은 계약일부터 10년 이내 연복리 1.0%, 10년 초과 연복리 0.25%입니다.'
dollar_base='연금개시시점 적립액은 조정된 이미 납입한 기본·추가보험료(생활자금형은 발생 생활자금 차감)+US$1을 최저로 합니다. 감액·중도인출은 약관상 납입보험료 및 적립액에 반영하여 계산합니다.'
for k,product in [('doc1','SOL메이트달러연금보험(무배당)'),('doc5','신한SOL메이트달러연금보험(무배당)')]:
 add(k,product,'고도재해장해급여금','주계약 피보험자가 연금개시 전 보험기간에 발생한 동일 재해를 직접 원인으로 장해분류표상 장해지급률 80% 이상의 장해상태가 된 경우. 질병장해나 연금개시 후 발생한 재해장해는 이 담보의 대상이 아닙니다.','US$10,000을 정액 지급합니다. 기본보험료에 80%를 곱하는 구조가 아니라 장해지급률 80%는 지급대상 여부의 기준입니다.',disability,'37–41,67','3–4')
 add(k,product,'생활자금(생활자금형)','생활자금형 계약에서 연금개시 전 계약일부터 만 1개월~만 120개월 시점의 각 월계약해당일에 유효하게 유지 중인 보험계약. 피보험자의 장해·질병 발생을 요건으로 하는 보험금이 아닌 생활자금 지급입니다.','이율확정기간(10년) 종료시 계약자적립액이 기본보험료와 같아지도록 산출한 매월 동일한 US$ 금액을 최대 120개월 지급합니다. 가입시 금액을 확정하며 같은 기본보험료라도 성별·가입나이에 따른 위험보험료로 월액이 달라질 수 있습니다. 감액으로 기본보험료가 바뀌면 생활자금도 변경됩니다.','생활자금형에만 적용하고 거치형에는 지급하지 않습니다. 계약이 해당 월 지급일에 유효해야 하며 발생 생활자금은 해당 시점 적립액에서 차감합니다. 연금개시시점까지 수령하지 않은 생활자금은 그때 이자를 반영하여 일시금으로 지급합니다. '+dollar_elig,'34,37–40,67','3–4,8–9')
 for form in ['거치형','생활자금형']:
  add(k,product,f'연금개시 전 사망시 지급금({form})',f'{form} 계약의 주계약 피보험자가 계약일부터 연금개시일 전일까지 사망한 경우. 지급받는 자는 계약자이며 생존연금·고도재해장해급여금과 구분합니다.','사망 당시 계약자적립액과 이미 납입한 기본·추가보험료'+('에서 발생 생활자금을 차감한 금액' if form=='생활자금형' else '')+' 중 큰 금액을 US$로 지급합니다. 적립액은 기본 적립액과 추가 적립액의 합계로 비용·위험보험료·인출'+('·생활자금' if form=='생활자금형' else '')+'을 반영한 금액입니다.','사망하면 해당 지급금을 계약자에게 지급하고 계약은 소멸합니다. 실종선고 또는 관공서 재난 사망통보는 약관상 사망일 기준을 적용합니다. 이미 납입한 보험료는 특약보험료를 제외하고 감액·인출 시 약관 산식으로 조정합니다. '+dollar_interest,'34,38–39,54,56,67','4–7')
 add(k,product,'종신연금형 생존연금','연금개시 후 종신연금형의 피보험자가 매년 연계약해당일에 생존한 경우. 보증지급기간 안에 사망하면 잔여 보증연금은 해당 보험수익자에게 지급합니다.','연금개시시점 계약자적립액에 연금사망률·공시이율을 적용하여 생존할 기간에 나누어 계산한 금액에서 계약관리비용을 차감한 US$ 연금액을 지급합니다. 보증기간은 10~20년 또는 100세 중 선택하며 정액 가입금액은 없습니다. '+dollar_base,'계약체결 시 선택 가능한 연금형태입니다. 생존 시 종신 지급하며 보증기간 중 사망해도 그 기간까지 연금을 지급합니다. 100세 보증은 100세 계약해당일 전일까지입니다. 보증기간 안의 잔여 보증연금은 공시이율로 할인한 일시금 선지급을 신청할 수 있습니다. 매월·3개월·6개월 분할 지급 시 해당 기간 공시이율을 적용하며 연금개시 후 해지는 제한됩니다. '+dollar_elig+' '+dollar_interest,'35,38,40,53,58,68–70','3–7')
 add(k,product,'확정연금형 연금','연금지급사항을 확정연금형으로 변경한 계약에서 선택 확정기간의 연계약해당일마다 지급받는 보험수익자. 피보험자의 생사와 관계없이 확정기간 동안 지급합니다.','연금개시시점 계약자적립액을 공시이율에 따라 선택 확정지급기간으로 나누어 계산하고 계약관리비용을 차감한 US$ 연금액입니다. 확정기간은 5~40년 또는 100세이며, 선택기간과 적립액·이율에 따라 실제 연금액이 결정됩니다. '+dollar_base,'계약체결 때 선택한 종신연금형을 연금개시일 전일까지 신청하여 변경한 계약에 적용합니다. 100세 확정은 100세 계약해당일 전일까지이며 다른 기간은 최종 연금 지급일까지 보장합니다. 확정기간 중 사망해도 잔여 연금을 지급하며 사망 후 잔여 확정분은 공시이율로 할인한 일시금 지급을 신청할 수 있습니다. 매월·3개월·6개월 분할 지급이 가능합니다. '+dollar_elig+' '+dollar_interest,'35,40,53,69–70','3–7')
 add(k,product,'상속연금형 생존연금','연금지급사항을 상속연금형으로 변경한 계약에서 연금개시 후 매년 연계약해당일에 생존한 피보험자. 원금성 적립액에 대한 이자를 연금으로 지급하는 형태입니다.','1차년도는 연금개시시점 적립액을 1년 전으로 할인한 금액의 1년 이자에서 계약관리비용을 차감합니다(개시시점 공시이율). 2차년도 이후는 개시 적립액에서 1차년도 연금액·계약관리비용을 차감한 금액의 직전 1년 이자에서 계약관리비용을 차감합니다(매 지급시점 직전 1년 공시이율). US$로 계산하며 고정 연금액이 아닙니다. '+dollar_base,'연금개시일 전일까지 상속연금형으로 변경한 계약에 적용합니다. 피보험자가 생존한 동안 지급하고 사망하면 생존연금 지급을 종료하여 사망 당시 적립액을 별도로 지급합니다. 매월·3개월·6개월 분할 지급 시 해당 기간 공시이율 적용 기준을 따릅니다. '+dollar_elig+' '+dollar_interest,'53,69–70','3–7')
 add(k,product,'상속연금형 사망시 지급금','상속연금형 계약의 연금개시 후 보험기간 중 사망한 피보험자에 대한 지급금. 생존연금의 보증지급기간을 적용하는 종신연금형과 구분합니다.','사망 당시의 상속연금형 계약자적립액을 US$로 지급합니다. 납입보험료 또는 고정 가입금액 전액을 무조건 지급하는 구조가 아니며 이미 발생한 연금·비용·인출을 반영한 해당 시점 적립액이 기준입니다.','실제 상속연금형으로 변경되어 있어야 하며 피보험자 사망 시 생존연금은 더 이상 지급하지 않습니다. '+dollar_interest,'34,53,69–70','3–7')
product='신한ONE더라이프연금보험(무배당)';k='doc3'
one_elig='연금개시나이는 50~80세, 가입나이는 0세~(연금개시나이−보험료 납입년수−5)세입니다. 월납 5·7·10·12·15·20·25·30년납이며 납입완료 후 최소거치기간은 5년입니다. 최소 기본보험료는 5년납 월 30만원, 7년납 및 10년납 이상 월 20만원입니다.'
one_interest='공시이율은 적립액 계산에 적용하며 최저보증은 계약일부터 10년 이내 연복리 1.0%, 10년 초과 0.25%입니다. 최저연금기준금액의 계산비율과 적립액의 공시이율은 서로 다른 기준입니다.'
one_adjust='감액·중도인출은 기준 기본·추가보험료, 최저연금기준금액·연금기준금액을 해당 적립액 비율로 재계산하므로 단순 납입총액만으로 금액을 확정하지 않습니다.'
one_min='최저연금기준금액은 기준 기본·추가보험료와 각 보험료의 납입일부터 발생한 지정 비율 해당액을 일자 계산하여 합한 금액입니다.'
add(k,product,'고도재해장해급여금','피보험자가 연금개시 전에 발생한 동일 재해로 연금개시 전 보험기간 중 여러 신체부위의 장해지급률 합계 80% 이상의 장해상태가 된 경우. 질병장해나 연금개시 후 사고에 대한 장해보장은 아닙니다.','1,000만원을 정액 지급합니다. 장해지급률 80%는 지급대상 판정 기준이며 보험료 또는 가입금액에 80%를 곱하여 지급하지 않습니다.',disability,'41–44,76','3–4')
for form in ['100세연금형','종신연금형']:
 rates='20년 이내 매년 7%, 20년 초과 매년 5%' if form=='100세연금형' else '20년 이내 매년 6%, 20년 초과 매년 4%'
 add(k,product,f'연금개시 전 사망시 지급금({form}·가입나이 만15세 이상)',f'{form} 가입 당시 피보험자 나이가 만 15세 이상이고 계약일부터 연금개시일 전일까지 사망한 경우. 지급받는 자는 계약자입니다.','max(사망 당시 계약자적립액, 사망 당시 최저연금기준금액)을 원화로 지급합니다. '+one_min+f' {form}의 기준금액 계산비율은 {rates}이며, 이 비율이 계약자적립액의 복리 수익률이나 현금보험금 지급률을 의미하지 않습니다.','사망 시 계약은 소멸하며 가입나이가 만 15세 미만인 계약의 납입보험료 기준과 구분합니다. 실종선고·관공서 재난 사망통보는 약관상 사망일을 적용합니다. '+one_adjust+' '+one_interest,'32–37,42,59–60,76','13–15')
 add(k,product,f'연금개시 후 사망시 지급금({form}·가입나이 만15세 이상)',f'{form} 가입 당시 피보험자 나이가 만 15세 이상이고 연금개시 후 해당 보험기간 중 사망한 경우. 지급받는 자는 계약자입니다.','max(사망 당시 계약자적립액, 최저사망지급금)을 원화로 지급합니다. 최저사망지급금 = max(사망시점 연금기준금액−연금개시 후 발생한 금리연동연금 연지급액 합계, 0). 개시시점 연금기준금액은 최저연금기준금액과 계약자적립액 중 큰 금액이며 인출 시 조정합니다.','기준금액에서 차감하는 연금은 이미 발생한 연금의 합계이므로 수령을 미뤘다는 이유만으로 미차감 원금을 별도로 보장하지 않습니다. 사망 지급 후 계약은 소멸합니다. '+one_adjust+' '+one_interest,'33–37,59–60,77','15–16')
add(k,product,'연금개시 전 사망시 지급금(가입나이 만15세 미만)','가입 당시 피보험자 나이가 만 15세 미만인 100세연금형 또는 종신연금형 계약에서 연금개시 전 사망한 경우. 가입 당시 나이로 적용 기준을 구분하며 지급받는 자는 계약자입니다.','사망 당시 계약자적립액과 이미 납입한 보험료 중 큰 금액을 원화로 지급합니다. 이미 납입한 보험료는 기본·추가보험료 누계(특약보험료 제외)이며 감액·인출이 있으면 약관 산식으로 조정합니다. 만 15세 이상 가입 계약의 최저연금기준금액을 이 계약에 그대로 적용하지 않습니다.','연금개시 전은 계약일부터 연금개시일 전일까지이며 사망 지급 후 계약은 소멸합니다. 실종선고·관공서 재난 사망통보도 약관상 기준을 적용합니다. '+one_interest,'33–34,37,42,59–60,76','11–12,15')
add(k,product,'연금개시 후 사망시 지급금(가입나이 만15세 미만)','가입 당시 피보험자 나이가 만 15세 미만인 100세연금형 또는 종신연금형 계약에서 연금개시 후 해당 보험기간 중 사망한 경우. 지급받는 자는 계약자입니다.','max(사망 당시 계약자적립액, 최저사망지급금)을 원화로 지급합니다. 최저사망지급금 = max(사망시점 이미 납입한 보험료−연금개시 후 발생한 금리연동연금 연지급액 합계, 0). 이미 납입한 보험료는 감액·인출을 반영한 기본·추가보험료 기준입니다.','가입 당시 만 15세 미만 기준을 적용하며 만 15세 이상 가입 계약의 연금기준금액 차감식과 구분합니다. 발생 연금액을 차감하고 사망 지급 후 계약은 소멸합니다. '+one_interest,'33–34,37,59–60,77','11–12,15')
ages=['50~54세','55~59세','60~64세','65~69세','70~74세','75세 이상']
for form,male,female in [('100세연금형',[3.02,3.27,3.60,4.05,4.55,5.20],[2.93,3.15,3.45,3.85,4.35,5.00]),('종신연금형',[2.82,3.07,3.40,3.85,4.35,5.00],[2.73,2.95,3.25,3.65,4.15,4.80])]:
 rates='; '.join(f'{age} 남 {v:.2f}%·여 {f:.2f}%' for age,v,f in zip(ages,male,female))
 ratio='최초 20년 이내 매년 7%, 20년 초과 매년 5%' if form=='100세연금형' else '최초 20년 이내 매년 6%, 20년 초과 매년 4%'
 amount='연지급액 = max(해당 시점 연금기준금액, 연계약해당일 계약자적립액) × 기본지급률 × (1+장기유지가산율). 개시시점 연금기준금액 = max(최저연금기준금액, 개시시점 적립액). 기본지급률은 개시나이·성별에 따라 '+rates+'. 가산율은 개시 전 보험기간 25년 미만 0%, 25~39년 30%, 40~54년 35%, 55년 이상 40%입니다. '+one_min+' 기준금액 계산비율은 '+ratio+'입니다. 지급률은 연금개시 시 결정되어 이후 동일하게 적용하지만 계산기준 금액은 인출 등을 반영합니다.'
 cond='계약자가 실제 선택한 보험종목에 적용합니다. 적립액이 0이 된 이후에도 생존 지급요건을 충족하면 연금을 계속 지급합니다. '+('지급기간은 개시일부터 피보험자 99세 계약해당일(약관의 100세 최종연금 지급일)까지이며 최종일 적립액이 연금액보다 크면 적립액을 지급합니다.' if form=='100세연금형' else '연금개시일부터 피보험자가 생존하는 동안 종신 지급합니다.')+' 개시시점 적립액은 조정된 이미 납입한 보험료+1,000원을 최저로 합니다. 매월·3개월·6개월 분할 지급은 산출방법서 기준을 적용합니다. '+one_adjust+' '+one_elig
 add(k,product,f'금리연동연금({form})',f'{form}을 선택한 주계약 피보험자가 연금개시 후 '+('100세 최종연금 지급일까지' if form=='100세연금형' else '종신 보험기간 중')+' 매년 연계약해당일에 생존한 경우. 개인별 개시나이·성별·개시 전 보험기간을 기준으로 지급률을 결정합니다.',amount,cond,'32–40,41–44,69–72,77','3–4,13–18')
assert len(r)==25 and len({(x['product_name'],x['coverage_name']) for x in r})==25
(p/'records.json').write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding='utf8')
